-- v31b: žvakės - originalai, natos, kvapai, aprašymai, spalvos, dagtis (vienodai visoms 18).
-- Natos - pagal originalų piramides. Paleisti galima kelis kartus.
begin;

-- Nauji ID (ON UPDATE CASCADE - produktai, krepšeliai, atsiliepimai seka patys)
update public.scents set id = 'scentdore' where id = 'scendore' and not exists (select 1 from public.scents where id = 'scentdore');
update public.products set id = 'kvapni-zvake-scentdore' where id = 'kvapni-zvake-scendore' and not exists (select 1 from public.products where id = 'kvapni-zvake-scentdore');
update public.scents set id = 'mavidore' where id = 'kvapni-zvake' and not exists (select 1 from public.scents where id = 'mavidore');
update public.products set id = 'kvapni-zvake-mavidore' where id = 'kvapni-zvake' and not exists (select 1 from public.products where id = 'kvapni-zvake-mavidore');

-- SIDORE (Giorgio Armani - Sì Passione)
update public.scents set name = 'SIDORE', inspired = 'Giorgio Armani - Sì Passione', gender = 'moterims', family = 'geliu', notes = '{"top": ["Kriaušė", "Juodieji serbentai", "Rožiniai pipirai", "Greipfrutas"], "heart": ["Rožė", "Jazminas", "Heliotropas", "Ananasas"], "base": ["Vanilė", "Kedras", "Pačiulis", "Gintaro mediena"]}'::jsonb where id = 'sired';
update public.products set inspired = 'Giorgio Armani - Sì Passione' where scent_id = 'sired';
update public.products set name = 'Kvapni žvakė SIDORE', scent_id = 'sired', inspired = 'Giorgio Armani - Sì Passione', gender = 'moterims', family = 'geliu', notes = '{"top": ["Kriaušė", "Juodieji serbentai", "Rožiniai pipirai", "Greipfrutas"], "heart": ["Rožė", "Jazminas", "Heliotropas", "Ananasas"], "base": ["Vanilė", "Kedras", "Pačiulis", "Gintaro mediena"]}'::jsonb, look = '{"cap": "gold", "shape": "rect", "tint": "#faeef0", "liquid": "#efc3cb"}'::jsonb, description = 'Kvapni žvakė SIDORE - sultingas vaisių ir gėlių aromatas jaukiai namų atmosferai. Viršutinės natos - kriaušė, juodieji serbentai, rožiniai pipirai ir greipfrutas, širdies - rožė, jazminas, heliotropas ir ananasas, bazinės - vanilė, kedras, pačiulis ir gintaro mediena. Pirmą kartą uždekite bent valandai, kad vaškas tolygiai išsilydytų visu paviršiumi. Namai prisipildo šilumos ir aistringos elegancijos.', longevity = 3, sillage = 3, attrs = coalesce(attrs, '{}'::jsonb) || '{"wick": "Medinė"}'::jsonb where id = 'kvapni-zvake-sired' and type = 'zvakes';

