-- Sì Passione: heliotropas - ir kitoms SIDORE prekėms (kvepalai, aliejus, difuzorius)
update public.products set notes = jsonb_set(notes, '{heart}', (notes->'heart') || '["Heliotropas"]'::jsonb) where scent_id = 'sired' and type <> 'zvakes' and jsonb_typeof(notes->'heart') = 'array' and not (notes->'heart') ? 'Heliotropas';

